INSERT INTO product (name, price, image_url, description) VALUES ('Multifunctional Multitool', 750, 'https://picsum.photos/800/800', 'Мултифункционален алат изработен од нерѓосувачки челик во црна боја. Содржи клешти, нож, ножици, шрафцигери, отворач и други практични алатки. Склопената должина изнесува 11 cm.');
INSERT INTO product (name, price, image_url, description) VALUES ('Car cleaning set', 2300, '/images/product-images/carDetailingKit.webp', 'Комплет за детално чистење на автомобил со микрофибер крпи, четки и сунѓерчиња. Сите додатоци се спакувани во компактна црна торбичка за лесно складирање и транспорт.');
INSERT INTO product (name, price, image_url, description) VALUES ('Power Bank 20.000 mAh', 4800, '/images/product-images/powerbank.webp', 'Power bank со капацитет од 20.000 mAh и црно куќиште. Опремен е со USB и USB-C приклучок и поддржува брзо полнење на мобилни телефони, слушалки и други USB уреди.');
INSERT INTO product (name, price, image_url, description) VALUES ('Rechargeable LED Flashlight', 500, '/images/product-images/flashlight.webp', 'LED батериска ламба со црно метално куќиште и USB приклучок за полнење. Има пет режими на осветлување и водоотпорно куќиште за користење во различни услови.');
INSERT INTO product (name, price, image_url, description) VALUES ('Beard Grooming Set', 1200, '/images/product-images/beardGroomingKit.webp', 'Комплет за нега на брада составен од четка, чешел, ножички и масло за брада. Додатоците се спакувани во црна декоративна кутија со компактен и практичен дизајн.');
INSERT INTO product (name, price, image_url, description) VALUES ('Electrical beard trimmer', 2000, '/images/product-images/beardTrimmer.webp', 'Безжичен електричен тример со црно-сребрено куќиште и повеќе наставци за различни должини на потстрижување. Се полни преку USB кабел и содржи четка за чистење.');
INSERT INTO product (name, price, image_url, description) VALUES ('Classic leather wallet', 1500, '/images/product-images/wallet.webp', 'Класичен и компактен паричник направен од вистинска кожа, има кафеава боја и совршена текстура.');
INSERT INTO product (name, price, image_url, description) VALUES ('Magnetic phone holder', 600, '/images/product-images/magneticPhoneHolder.webp', 'Магнетен држач за телефон со црно алуминиумско куќиште и силен магнет. Се поставува на вентилациониот отвор во автомобилот и овозможува стабилно држење на телефонот.');
INSERT INTO product (name, price, image_url, description) VALUES ('Bluetooth Key Finder', 300, '/images/product-images/keyFinder.webp', 'Bluetooth tracker со компактно црно куќиште со дијаметар од 36 mm. Се поврзува со мобилен телефон и овозможува пронаоѓање на прикачени предмети преку мобилна апликација.');
INSERT INTO product (name, price, image_url, description) VALUES ('BBQ Grill Tool Set', 850, '/images/product-images/bbqGrillSet.webp', 'Сет од три алатки за скара изработени од нерѓосувачки челик со црни рачки. Комплетот содржи клешти, шпатула и виљушка и доаѓа во црна торбичка за складирање.');
INSERT INTO product (name, price, image_url, description) VALUES ('Stainless steel bottle', 400, '/images/product-images/thermos.webp', 'Термос шише со капацитет од 500 ml, изработено од нерѓосувачки челик со мат црна завршница. Двојниот изолиран ѕид ја одржува температурата на пијалакот, а капачето обезбедува непропустливо затворање.');
INSERT INTO product (name, price, image_url, description) VALUES ('Whiskey Glass Set', 2000, '/images/product-images/wiskeyGlasses.webp', 'Подарочен сет со две стаклени чаши за виски и четири коцки за ладење изработени од природен камен. Сетот е спакуван во елегантна црна подарочна кутија.');
INSERT INTO product (name, price, image_url, description) VALUES ('Miniature car model', 1800, '/images/product-images/miniatureCar.webp', 'Детален метален модел на спортски автомобил во размер 1:24. Моделот има метална каросерија, гумени тркала, детална внатрешност и отворачки врати.');
INSERT INTO product (name, price, image_url, description) VALUES ('Pocket knife', 2000, '/images/product-images/pocketKnife.webp', 'Преклопен нож од премиум Дамаскус челик со препознатлива рурална текстура и вкупна должина од 20 cm (сечило 9 cm).Во комплетот доаѓа со кожна футрола за носење на ремен и мало острило со украсена метална дршка.');
INSERT INTO product (name, price, image_url, description) VALUES ('Gym straps', 300, '/images/product-images/gymStraps.webp', 'Фитнес сет со црни lifting straps и рачни grip тренери. Текстилните straps имаат засилени шевови, а grip тренерите се изработени од цврста пластика со гумени рачки.');
INSERT INTO product (name, price, image_url, description) VALUES ('Fishing Tackle Set', 1000, '/images/product-images/fishingSet.webp', 'Комплет за риболов спакуван во компактна пластична кутија со прегради. Содржи риболовни мамки, куки, вртливки и други основни додатоци за риболов.');
INSERT INTO product (name, price, image_url, description) VALUES ('Outdoor Survival Kit', 1500, '/images/product-images/survivalKit.webp', 'Survival сет со основни алатки за активности на отворено, спакувани во црна водоотпорна футрола. Комплетот содржи мултифункционална алатка, компас, свирче и огнивце.');
INSERT INTO product (name, price, image_url, description) VALUES ('Screwdriver Set', 700, '/images/product-images/screwdriver.webp', 'Комплет за прецизно одвртување со метална рачка и 24 различни битови. Сите делови се организирани во компактна црна кутија со магнетен држач за битовите.');
INSERT INTO product (name, price, image_url, description) VALUES ('Mechanical wristwatch', 6000, '/images/product-images/mechanicalWatch.webp', 'Елегантен механички часовник со класичен ретро дизајн и куќиште од нерѓосувачки челик со пречник од 38 mm. Одликува со сребренест бројчаник со златни стрелки. Комбиниран е со кафеаво кожно ремче со рачно сошиени детали.');
INSERT INTO product (name, price, image_url, description) VALUES ('Cigar set', 4500, '/images/product-images/cigarSet.webp', 'Сет за пури од ореово дрво со стаклен капак и вграден дигитален влагомер за прецизна контрола на влажноста. Комплетот вклучува навлажнувач, секач за пури, метален клуч, како и елегантна кожна футрола и запалка.');
